@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Russo+One&display=swap');
:root{color-scheme:dark;--ink:#f7f0e2;--muted:#a19caf;--gold:#ffcc72;--pink:#ff7895;--panel:#171925}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:#10121b;color:var(--ink);font-family:'DM Sans',sans-serif;display:grid;place-items:center;padding:22px;background-image:radial-gradient(ellipse at 50% 28%,#28273a 0,transparent 58%),linear-gradient(130deg,#10121b,#171722 60%,#12141f)}button{font:inherit;color:inherit}.game-shell{width:min(1120px,100%)}.topbar,.bottom-bar{height:48px;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:#eee9e4;font-family:'DM Mono',monospace;font-size:12px;letter-spacing:1.6px}.brand b{color:var(--gold);font-weight:500}.brand-icon{font-size:23px;color:var(--gold)}.top-actions{display:flex;align-items:center;gap:22px}.online,.icon-button,.round-label,.controls-legend,.footer-note{font:10px 'DM Mono',monospace;letter-spacing:1px;color:#a6a4b1}.online{display:flex;align-items:center;gap:8px}.online i{width:7px;height:7px;border-radius:50%;background:#83dba9;box-shadow:0 0 11px #83dba9}.icon-button{border:1px solid #343443;background:#1a1b28;padding:8px 11px;border-radius:7px;cursor:pointer;color:var(--gold)}.icon-button span{font-size:9px;color:#aaa;margin-left:4px}.game-frame{position:relative;width:100%;aspect-ratio:16/9;overflow:hidden;border:1px solid #494252;border-radius:13px;background:#242435;box-shadow:0 24px 80px #080910aa,0 0 0 5px #ffffff04}canvas{width:100%;height:100%;display:block;touch-action:none}.overlay{position:absolute;inset:0;display:grid;place-items:center;background:linear-gradient(90deg,rgba(13,14,25,.45),rgba(14,15,27,.02) 46%,rgba(13,14,25,.16)),linear-gradient(0deg,#10121dbb,transparent 40%);transition:opacity .35s}.overlay.hidden{opacity:0;pointer-events:none}.menu-card{position:absolute;left:8%;top:9%;width:41%;max-width:390px;text-align:left}.eyebrow{font:10px 'DM Mono',monospace;letter-spacing:2px;color:var(--gold);margin-bottom:13px}.eyebrow span{opacity:.7}.menu-card h1{font:clamp(34px,5.3vw,60px)/.93 'Russo One',sans-serif;letter-spacing:1px;margin:0;text-shadow:0 4px 20px #0008}.menu-card h1 em{font-style:normal;color:var(--gold)}.tagline{font-size:13px;line-height:1.55;color:#d0ccd0;margin:13px 0}.tagline b{color:#ffb4bf}.roster{display:flex;gap:7px;margin:15px 0 13px}.fighter-choice{width:43px;height:48px;border:1px solid #6c6570;background:#191925d9;border-radius:7px;cursor:pointer;position:relative;display:grid;place-items:center;transition:.18s;overflow:hidden}.fighter-choice:hover{transform:translateY(-3px);border-color:#fff}.fighter-choice.selected{border-color:var(--gold);box-shadow:0 0 0 1px var(--gold),0 0 17px #ffc76d44}.fighter-choice canvas{width:42px;height:46px}.fighter-choice .choice-num{position:absolute;right:4px;bottom:2px;font:8px 'DM Mono',monospace;color:#ded6cf;text-shadow:0 1px 3px #000}.selected-name{font:10px 'DM Mono',monospace;letter-spacing:1.3px;color:var(--gold);margin:-5px 0 10px}.play-button{width:100%;height:43px;border:0;border-radius:5px;background:linear-gradient(100deg,#ffcb75,#f1a94f);color:#2c1b19;font:14px 'Russo One',sans-serif;letter-spacing:1.3px;box-shadow:0 5px 20px #ffa95633;cursor:pointer;transition:.18s}.play-button:hover{filter:brightness(1.12);transform:translateY(-2px)}.play-button span{float:right;margin-right:10px}.menu-tip{color:#a7a3b1;font:9px 'DM Mono',monospace;letter-spacing:.3px;text-align:center;margin-top:8px}.menu-side-note{position:absolute;right:5%;top:13%;font:10px 'DM Mono',monospace;letter-spacing:2px;color:#e3ddde;text-align:right;line-height:1.8}.menu-side-note b{font:48px 'Russo One',sans-serif;color:#fff4df;letter-spacing:0}.menu-side-note span{color:var(--gold)}.menu-controls{position:absolute;bottom:16px;left:22px;color:#b9b4be;font:9px 'DM Mono',monospace;letter-spacing:.5px}.menu-controls span{color:var(--gold);margin-right:8px}.menu-controls i{font-style:normal;color:#eac67e}.bottom-bar{height:47px}.controls-legend{display:flex;align-items:center;gap:15px;font-size:9px}.controls-legend span{display:flex;align-items:center;gap:5px}.controls-legend kbd{font:9px 'DM Mono',monospace;color:#ece3d5;border:1px solid #484550;background:#20212c;border-radius:3px;padding:3px 5px}.footer-note{font-size:9px;letter-spacing:1.1px}.footer-note b{color:var(--gold);font-size:14px;margin-left:6px}.fight-ui{position:absolute;top:17px;left:5%;right:5%;display:grid;grid-template-columns:1fr 54px 1fr;gap:16px;align-items:center;pointer-events:none}.fight-ui.hidden{display:none}.fighter-hud{min-width:0}.hud-top{display:flex;align-items:center;justify-content:space-between;margin:0 2px 6px;font:15px 'Russo One',sans-serif;letter-spacing:1px;text-shadow:0 2px 4px #000}.cpu-hud .hud-top{flex-direction:row-reverse}.round-label{font-size:8px;color:#e5c986}.health-track,.power-track{height:13px;background:#201b2a;border:2px solid #e8dfd3;border-radius:4px;overflow:hidden;box-shadow:0 2px 7px #0008;transform:skewX(-7deg)}.cpu-hud .health-track,.cpu-hud .power-track{transform:skewX(7deg)}.health-fill{height:100%;width:100%;background:linear-gradient(90deg,#f8cb71,#f18076);transition:width .18s}.cpu-hud .health-fill{margin-left:auto;background:linear-gradient(90deg,#f18076,#f8cb71)}.power-track{height:5px;border:0;margin-top:4px;background:#31293c}.power-fill{height:100%;width:0;background:#77e4d4;transition:width .2s}.cpu-hud .power-fill{margin-left:auto;background:#a98dff}.round-badge{text-align:center;background:#171523dd;border:1px solid #c8a96e;border-radius:6px;padding:5px 3px;box-shadow:0 3px 12px #0007}.round-badge span{display:block;font:7px 'DM Mono',monospace;letter-spacing:1px;color:#d2c2a8}.round-badge b{font:21px 'Russo One',sans-serif;color:#ffe0a2}.announcement{position:absolute;left:0;right:0;top:39%;text-align:center;font:clamp(34px,6vw,65px) 'Russo One',sans-serif;letter-spacing:4px;color:#ffe6a9;text-shadow:0 4px 0 #793a46,0 8px 30px #000;pointer-events:none;animation:announce .9s both}.announcement.hidden{display:none}.pause-badge{position:absolute;inset:0;display:grid;place-content:center;text-align:center;background:#141322aa;font:36px 'Russo One',sans-serif;color:#fff0c8;letter-spacing:4px}.pause-badge small{margin-top:7px;font:10px 'DM Mono',monospace;letter-spacing:1px;color:#cbc2c2}.pause-badge.hidden{display:none}@keyframes announce{0%{transform:scale(1.45);opacity:0}20%{transform:scale(1);opacity:1}75%{opacity:1}100%{opacity:0;transform:scale(.94)}}
@media(max-width:700px){body{padding:8px}.topbar{height:36px}.brand{font-size:10px}.online{display:none}.game-frame{border-radius:8px}.menu-card{left:6%;top:6%;width:48%}.eyebrow{font-size:7px;letter-spacing:1px;margin-bottom:8px}.menu-card h1{font-size:clamp(26px,7vw,43px)}.tagline{font-size:10px;margin:8px 0}.roster{gap:4px;margin:9px 0 12px}.fighter-choice{width:32px;height:38px}.fighter-choice canvas{width:32px;height:36px}.selected-name{font-size:8px;margin:-6px 0 7px}.play-button{height:34px;font-size:11px}.menu-tip{font-size:7px;margin-top:6px}.menu-side-note{font-size:7px;top:9%;right:4%}.menu-side-note b{font-size:32px}.menu-controls{font-size:7px;bottom:8px;left:10px}.menu-controls span{display:none}.bottom-bar{height:auto;min-height:38px}.controls-legend{gap:6px;font-size:7px}.controls-legend span{gap:3px}.controls-legend kbd{font-size:7px;padding:2px 3px}.footer-note{font-size:7px}.fight-ui{top:9px;grid-template-columns:1fr 37px 1fr;gap:7px}.hud-top{font-size:10px;margin-bottom:3px}.round-label{font-size:6px}.health-track{height:9px}.round-badge{padding:3px 2px}.round-badge span{font-size:6px}.round-badge b{font-size:15px}}
@media(max-width:420px){.menu-side-note{display:none}.menu-card{width:56%}.footer-note{display:none}.controls-legend{width:100%;justify-content:space-between}.tagline{font-size:9px}}

